def build_zim(path, metadata, entries, main_path=None):
    """A ZIM at ``path`` with ``metadata`` and ``entries``, ``{path: (mimetype,
    bytes or str, title)}``; pages are front articles. libzim writes the
    Counter of mimetypes itself, as it does for Kiwix's builds."""
    from libzim.writer import Blob, ContentProvider, Creator, Hint, Item

    class _Provider(ContentProvider):
        def __init__(self, data):
            super().__init__()
            self.data, self.fed = data, False

        def get_size(self):
            return len(self.data)

        def feed(self):
            if self.fed:
                return Blob(b"")
            self.fed = True
            return Blob(self.data)

    class _Entry(Item):
        def __init__(self, p, mime, data, title):
            super().__init__()
            self.p, self.mime, self.title = p, mime, title
            self.data = data.encode("utf-8") if isinstance(data, str) else data

        def get_path(self):
            return self.p

        def get_title(self):
            return self.title

        def get_mimetype(self):
            return self.mime

        def get_contentprovider(self):
            return _Provider(self.data)

        def get_hints(self):
            return {Hint.FRONT_ARTICLE: self.mime.startswith("text/html")}

    with Creator(path).config_indexing(False, "eng") as creator:
        creator.set_mainpath(main_path or next(iter(entries)))
        for p, (mime, data, title) in entries.items():
            creator.add_item(_Entry(p, mime, data, title))
        meta = {"Title": "Fixture", "Language": "eng", "Description": "fixture"}
        meta.update(metadata)
        for key, value in meta.items():
            creator.add_metadata(key, value)
    return path
